let CONFIG=structuredClone(LOCAL_CONFIG);
const DEFAULT_RESTAURANT=LOCAL_CONFIG.restaurant;
const DEFAULT_THEME=LOCAL_CONFIG.theme;
function escapeHtml(value) {
    return String(value ?? '').replace(/[&<>"']/g, ch => ({
        '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'
    }[ch]));
}


// Combina el menú guardado en el panel con el menú del código.
// Así una configuración remota antigua no puede desactivar funciones nuevas.
function mergeMenuData(remoteMenu, localMenu) {
    return structuredClone(Array.isArray(remoteMenu) ? remoteMenu : localMenu);
}

function mergeConfig(remote) {
    return {
        ...LOCAL_CONFIG,
        ...(remote || {}),
        restaurant: { ...DEFAULT_RESTAURANT, ...((remote || {}).restaurant || {}) },
        theme: { ...DEFAULT_THEME, ...((remote || {}).theme || {}) },
        schedule: { ...LOCAL_CONFIG.schedule, ...((remote || {}).schedule || {}) },
        storeStatus: { ...LOCAL_CONFIG.storeStatus, ...((remote || {}).storeStatus || {}) },
        googleReviews: { ...LOCAL_CONFIG.googleReviews, ...((remote || {}).googleReviews || {}) },
        menuData: mergeMenuData((remote || {}).menuData, LOCAL_CONFIG.menuData),
        deliveryCost: Number.isFinite(Number((remote || {}).deliveryCost))
            ? Number((remote || {}).deliveryCost)
            : 6000,
        exchangeDivisors: remote && Object.hasOwn(remote,'exchangeDivisors')
            ? { usd: BenchoMoney.divider(remote.exchangeDivisors?.usd), bs: BenchoMoney.divider(remote.exchangeDivisors?.bs) }
            : (remote?.payments ? BenchoMoney.legacyDivisors(remote.payments) : { ...LOCAL_CONFIG.exchangeDivisors }),
        paymentMethods: BenchoMoney.paymentMethods(remote || LOCAL_CONFIG),
        deliveryZones: Array.isArray((remote || {}).deliveryZones)
            ? (remote || {}).deliveryZones.map(z => ({
                name: String(z?.name || '').trim(),
                price: Math.max(0, Number(z?.price) || 0)
            })).filter(z => z.name)
            : (Array.isArray(LOCAL_CONFIG.deliveryZones) ? LOCAL_CONFIG.deliveryZones : []),
        hoursText: (remote || {}).hoursText || formatConfiguredHours({ ...LOCAL_CONFIG.schedule, ...((remote || {}).schedule || {}) })
    };
}

async function loadRemoteConfig() {
    const response = await fetch('/api/config', { cache: 'no-store' });
    if (!response.ok) throw new Error(`API ${response.status}`);
    CONFIG = mergeConfig(await response.json());
    renderDeliveryZones();
    renderPaymentMethods();
    window.dispatchEvent(new CustomEvent('bencho:config', {detail: CONFIG}));
}

function applyTheme() {
    const t = CONFIG.theme || DEFAULT_THEME;
    const root = document.documentElement;
    root.style.setProperty('--primary', t.primary || DEFAULT_THEME.primary);
    root.style.setProperty('--primary-hover', t.primaryHover || DEFAULT_THEME.primaryHover);
    root.style.setProperty('--accent', t.accent || DEFAULT_THEME.accent);
    root.style.setProperty('--accent-hover', t.accentHover || DEFAULT_THEME.accentHover);
    root.style.setProperty('--danger', t.danger || DEFAULT_THEME.danger);
}

function applyRestaurantConfig() {
    const r = CONFIG.restaurant || DEFAULT_RESTAURANT;
    const byId = id => document.getElementById(id);

    const logo = byId('restaurant-logo');
    if (logo && r.logo) {
        logo.src = r.logo;
        logo.alt = `${r.name || 'Bencho 1:9'} Logo`;
    }

    const watermark = byId('watermark-logo');
    if (watermark && r.watermark) watermark.src = r.watermark;

    const cover = r.cover || 'images/portada.webp';
    if (cover) document.documentElement.style.setProperty('--restaurant-cover', `url("${cover}")`);

    const favicon = byId('site-favicon');
    if (favicon && r.logo) favicon.href = r.logo;
    const apple = byId('site-apple-icon');
    if (apple && r.logo) apple.href = r.logo;

    const setText = (id, value) => {
        const el = byId(id);
        if (el && value != null) el.textContent = value;
    };

    setText('restaurant-name', r.name);
    setText('restaurant-subtitle', r.subtitle);
    setText('restaurant-slogan', r.slogan);
    setText('store-hours-top', CONFIG.hoursText);

    const loc = byId('restaurant-location');
    if (loc && r.location) {
        loc.innerHTML = `📍 <strong>Dirección:</strong> ${escapeHtml(r.location)}`;
    }

    const insta = byId('restaurant-instagram');
    if (insta && r.instagram) insta.href = safeLink(r.instagram);

    const tiktok = byId('restaurant-tiktok');
    if (tiktok && r.tiktok) tiktok.href = safeLink(r.tiktok);

    const footer = byId('restaurant-footer');
    if (footer) {
        footer.innerHTML = `&copy; ${escapeHtml(r.fullName || r.name || 'Bencho 1:9')} - ${escapeHtml((r.location || '').split(',')[0])}`;
    }

    const title = document.querySelector('title');
    if (title) title.textContent = `${r.name || 'Bencho 1:9'} | Menú y Pedidos`;

    const desc = document.querySelector('meta[name="description"]');
    if (desc && r.description) desc.setAttribute('content', r.description);

    const ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) ogTitle.setAttribute('content', `${r.name || 'Bencho 1:9'} | Menú y Pedidos`);

    const ogDesc = document.querySelector('meta[property="og:description"]');
    if (ogDesc && r.description) ogDesc.setAttribute('content', r.description);
}

function getDeliveryZones() {
    return Array.isArray(CONFIG.deliveryZones)
        ? CONFIG.deliveryZones.filter(z => z && String(z.name || '').trim())
        : [];
}

function getSelectedDeliveryZone() {
    const select = document.getElementById('delivery-zone');
    const zones = getDeliveryZones();
    if (!zones.length) return null;
    const index = Number(select?.value);
    return Number.isInteger(index) && zones[index] ? zones[index] : zones[0];
}

function renderDeliveryZones() {
    const group = document.getElementById('delivery-zone-group');
    const select = document.getElementById('delivery-zone');
    if (!group || !select) return;
    const zones = getDeliveryZones();
    if (!zones.length) {
        group.style.display = 'none';
        return;
    }
    const previous = select.value;
    select.innerHTML = zones.map((zone, index) =>
        `<option value="${index}">${escapeHtml(zone.name)} — ${formatMoney(zone.price || 0)}</option>`
    ).join('');
    if (zones[Number(previous)]) select.value = previous;
    group.style.display = document.getElementById('order-type')?.value === 'Delivery' ? 'block' : 'none';
}

function handleDeliveryZoneChange() {
    renderCart();
}

function getDeliveryCost() {
    const selected = getSelectedDeliveryZone();
    if (selected) {
        const price = Number(selected.price);
        return Number.isFinite(price) && price >= 0 ? price : 0;
    }
    const base = Number(CONFIG.deliveryCost ?? 6000);
    return Number.isFinite(base) && base >= 0 ? base : 6000;
}

function loadSavedCart() {
    const clean = Object.create(null);
    try {
      const saved=JSON.parse(localStorage.getItem('bencho19_cart'));
      if(!saved || typeof saved!=='object' || Array.isArray(saved))return clean;
      for(const [name,item] of Object.entries(saved).slice(0,200)) {
        if(name.length<=300 && item && Number.isFinite(item.price) && item.price>=0 && item.price<=1e9 && Number.isInteger(item.qty) && item.qty>0 && item.qty<=50) clean[name]={...item,price:item.price,qty:item.qty};
      }
    } catch {}
    return clean;
}
let cart = loadSavedCart();
let currentAddonPending = null;
const dayNames = { 3: "Miércoles", 4: "Jueves", 5: "Viernes" };

function getVzlaNow() {
    const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Caracas', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
    const map = {};
    parts.forEach(p => { map[p.type] = p.value; });
    const weekdayMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
    let hour = parseInt(map.hour, 10);
    if (hour === 24) hour = 0;
    return { day: weekdayMap[map.weekday], hour: hour, minute: parseInt(map.minute, 10) };
}

function normalizeConfiguredTime(value, fallback) {
    const text = String(value || '').trim();
    return /^([01]\d|2[0-3]):[0-5]\d$/.test(text) ? text : fallback;
}

function configuredMinutes(value, fallback) {
    const normalized = normalizeConfiguredTime(value, fallback);
    const [h, m] = normalized.split(':').map(Number);
    return h * 60 + m;
}

function formatConfiguredTime(value, fallback) {
    const normalized = normalizeConfiguredTime(value, fallback);
    const [h, m] = normalized.split(':').map(Number);
    const suffix = h >= 12 ? 'pm' : 'am';
    const displayHour = h % 12 || 12;
    return `${displayHour}:${String(m).padStart(2, '0')} ${suffix}`;
}

function getConfiguredSchedule() {
    return {
        openingTime: normalizeConfiguredTime(CONFIG.schedule?.openingTime, '11:00'),
        closingTime: normalizeConfiguredTime(CONFIG.schedule?.closingTime, '15:00'),
        secondOpeningTime: normalizeConfiguredTime(CONFIG.schedule?.secondOpeningTime, '18:00'),
        secondClosingTime: normalizeConfiguredTime(CONFIG.schedule?.secondClosingTime, '23:00'),
        secondShiftEnabled: CONFIG.schedule?.secondShiftEnabled !== false
    };
}

function formatConfiguredHours(schedule) {
    const s = { openingTime:'11:00', closingTime:'15:00', secondOpeningTime:'18:00', secondClosingTime:'23:00', secondShiftEnabled:true, ...(schedule || {}) };
    const first = `${formatConfiguredTime(s.openingTime, '11:00')} - ${formatConfiguredTime(s.closingTime, '15:00')}`;
    if (s.secondShiftEnabled === false) return `Todos los días: ${first}`;
    const second = `${formatConfiguredTime(s.secondOpeningTime, '18:00')} - ${formatConfiguredTime(s.secondClosingTime, '23:00')}`;
    return `Todos los días: ${first} y ${second}`;
}

function isWithinConfiguredShift(currentMin, openingMin, closingMin) {
    if (openingMin === closingMin) return true;
    if (closingMin > openingMin) return currentMin >= openingMin && currentMin < closingMin;
    return currentMin >= openingMin || currentMin < closingMin;
}

function isStoreOpen() {
    if (!/^\d{10,15}$/.test(String(CONFIG.restaurant?.whatsapp||''))) return false;
    if (CONFIG.storeStatus.forceClose) return false;
    const dateStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Caracas' }).format(new Date());
    if ((CONFIG.storeStatus.specialClosedDates || []).includes(dateStr)) return false;

    const { day, hour, minute } = getVzlaNow();


    const currentMin = hour * 60 + minute;
    const schedule = getConfiguredSchedule();
    const firstShift = isWithinConfiguredShift(currentMin, configuredMinutes(schedule.openingTime, 11 * 60), configuredMinutes(schedule.closingTime, 15 * 60));
    if (schedule.secondShiftEnabled === false) return firstShift;

    const secondShift = isWithinConfiguredShift(currentMin, configuredMinutes(schedule.secondOpeningTime, 18 * 60), configuredMinutes(schedule.secondClosingTime, 23 * 60));
    return firstShift || secondShift;
}

function openImageModal(src, description) {
    const modal = document.getElementById('image-modal');
    const modalImg = document.getElementById('modal-img');
    if (!modal || !modalImg || !src) return;
    modalImg.alt = description || 'Producto del menú de Bencho 1:9';
    modalImg.src = src;
    modal.style.setProperty('display', 'flex', 'important');
}

function closeImageModal() {
    const modal = document.getElementById('image-modal');
    const modalImg = document.getElementById('modal-img');
    if (!modal) return;
    modal.style.setProperty('display', 'none', 'important');
    if (modalImg) modalImg.removeAttribute('src');
}

// Nunca mostrar el modal al cargar la página.
document.addEventListener('DOMContentLoaded', () => closeImageModal());

function scrollToCategory(event, catId) {
    window.BenchoCategories?.navigate(event, catId);
}

function renderMenuHTML() {
    const container=document.getElementById('menu-container'), navBar=document.getElementById('category-nav-bar');
    let html='',navHTML='';
    CONFIG.menuData.forEach((cat,catIndex)=>{
        if(cat.isHidden===true)return;
        const catId=`cat-section-${catIndex}`, burgers=cat.items.some(item=>/^b19-burger-/.test(item.id||''));
        navHTML+=`<a href="#${catId}" class="cat-pill" data-scroll-category="${catId}">${escapeHtml(cat.category)}<span>${cat.items.length}</span></a>`;
        html+=`<section class="menu-category ${burgers?'burger-category':'extras-category'}" id="${catId}" aria-labelledby="${catId}-title"><h3 class="category-name" id="${catId}-title">${escapeHtml(cat.category)}</h3>`;
        const items=cat.items.map((item,index)=>({item,index})).sort((a,b)=>Number(!!b.item.isFeatured)-Number(!!a.item.isFeatured));
        items.forEach(({item,index:itemIndex})=>{
            const uniqueId=`item-${catIndex}-${itemIndex}`, soldOut=item.outOfStock===true||item.isSoldOut===true, pending=!(item.price>0);
            const grams=String(item.description||'').match(/(\d+)\s*g\s+de carne/i)?.[1];
            const included=burgers&&/Incluye 100 g de papas fritas\.?/i.test(item.description||'');
            const description=included?item.description.replace(/\s*Incluye 100 g de papas fritas\.?/i,''):item.description;
            const img=item.image?`<img src="${escapeHtml(item.image)}" data-image="${escapeHtml(item.image)}" alt="${escapeHtml(item.name)}" class="item-img" loading="lazy" width="80" height="80">`:'';
            html+=`<article class="menu-item ${burgers?'burger-card':''} ${item.isFeatured?'featured-item':''} ${soldOut?'promo-disabled':''} ${item.promoDay?'promo-item':''}" ${item.id?`id="${escapeHtml(item.id)}"`:''} ${item.promoDay?`data-day="${Number(item.promoDay)}"`:''}>`;
            if(burgers)html+=`<div class="burger-card-top"><span>BENCHO 1:9 / ${String(itemIndex+1).padStart(2,'0')}</span>${grams?`<span class="burger-weight">${grams} G</span>`:''}</div>`;
            html+=`<div class="menu-item-top">${img}<div class="item-info"><h4 class="item-name">${escapeHtml(item.name)}</h4>${item.isFeatured?'<span class="featured-badge">DESTACADO</span>':''}</div></div>`;
            if(description)html+=`<p class="item-description">${escapeHtml(description)}</p>`;
            if(included)html+='<span class="fries-note"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="m5 10 2 11h10l2-11-4 3H9L5 10Z"/><path d="M7 11V4h3v8m1 0V2h3v10m1 0V5h3v6"/></svg>Incluye 100 g de papas fritas</span>';
            if(item.proteinSelector&&!soldOut)html+=`<label class="item-options">Proteína<select id="sel-${uniqueId}" class="item-select">${item.proteinSelector.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('')}</select></label>`;
            html+=`<div class="item-bottom"><span class="item-price ${pending?'pending-price':''}">${pending?'Precio por confirmar':moneyMarkup(item.price)}</span>`;
            if(soldOut)html+='<button class="btn-add" disabled>Agotado</button>';
            else if(pending)html+=`<a class="price-pending-link" href="https://www.instagram.com/bencho1.9/" target="_blank" rel="noopener noreferrer" aria-label="Consultar ${escapeHtml(item.name)} en Instagram">Consultar <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></a>`;
            else html+=`<button class="btn-add btn-menu-action ${item.promoDay?'btn-promo':''}" data-menu-add="${uniqueId}" data-category-index="${catIndex}" data-item-index="${itemIndex}" data-featured="${!!item.isFeatured}" aria-label="Agregar ${escapeHtml(item.name)} a mi pedido">Agregar <span aria-hidden="true">+</span></button>`;
            html+='</div></article>';
        });
        html+='</section>';
    });
    if(navBar)navBar.innerHTML=navHTML;
    container.innerHTML=html;
    container.querySelectorAll('.item-img[data-image]').forEach(img=>img.addEventListener('click',()=>openImageModal(img.dataset.image,img.alt)));
}


function populateReviews() {}

function refreshStoreStatusUI() {
    const ready=/^\d{8,15}$/.test(String(CONFIG.restaurant.whatsapp||'').replace(/\D/g,''))&&CONFIG.menuData.some(c=>c.items.some(i=>i.price>0));
    const explainer=document.querySelector('.currency-explainer');
    if(explainer)explainer.textContent=ready?'Precios en COP. El restaurante confirma el total y la disponibilidad.':'Estamos preparando los precios. Mientras tanto, explora la carta y consulta en Instagram.';
    if(!ready){
        const badge=document.getElementById('store-status-badge'),banner=document.getElementById('store-closed-alert'),button=document.getElementById('btn-send-whatsapp');
        if(badge){badge.textContent='CONOCE NUESTRA CARTA';badge.className='status-tag pending';}
        if(banner){banner.style.display='block';banner.textContent='Los pedidos se habilitarán al confirmar precios y contacto. Puedes consultar las novedades en Instagram.';}
        if(button){button.disabled=true;button.textContent='Pedidos próximamente';}return;
    }
    const isOpen = isStoreOpen();
    const badge = document.getElementById('store-status-badge');
    const closedBanner = document.getElementById('store-closed-alert');
    const btnWs = document.getElementById('btn-send-whatsapp');

    if (isOpen) {
        if (badge) {
            badge.innerText = '🟢 ABIERTO AHORA';
            badge.className = 'status-tag open';
        }
        if (closedBanner) closedBanner.style.display = 'none';
        if (btnWs) { 
            btnWs.disabled = false; 
            btnWs.textContent = 'Enviar pedido por WhatsApp'; 
        }
    } else {
        if (badge) {
            badge.innerText = '🔴 CERRADO AHORA';
            badge.className = 'status-tag closed';
        }
        if (closedBanner) closedBanner.style.display = 'block';
        if (btnWs) { 
            btnWs.disabled = true; 
            btnWs.innerHTML = '<span>🔴</span> Local Cerrado'; 
        }
    }

    document.querySelectorAll('.btn-menu-action').forEach(btn => {
        const item = btn.closest('.menu-item');
        if (item && item.classList.contains('promo-disabled')) return;
        btn.disabled = !isOpen;
        btn.innerText = isOpen ? '+ Agregar' : 'Cerrado';
    });
}

window.addEventListener('DOMContentLoaded', async () => {
    try {
        await loadRemoteConfig();
    } catch (error) {
        console.warn('No se pudo cargar la configuración remota; se usa la configuración local.', error);
        CONFIG = structuredClone(LOCAL_CONFIG);
    }

    applyTheme();
    applyRestaurantConfig();

    renderMenuHTML();
    populateReviews();
    renderCart();

    const { day: today } = getVzlaNow();
    const promoItems = document.querySelectorAll('.promo-item');
    
    promoItems.forEach(item => {
        const targetDay = parseInt(item.getAttribute('data-day'));
        const pBadge = item.querySelector('.promo-badge');
        const btn = item.querySelector('.btn-promo');

        if (today === targetDay) {
            if (pBadge) { pBadge.innerText = "🔥 ¡DISPONIBLE HOY!"; pBadge.classList.add('active'); }
        } else {
            if (pBadge) { pBadge.innerText = `Solo los ${dayNames[targetDay]}`; pBadge.classList.add('inactive'); }
            item.classList.add('promo-disabled');
            if (btn) btn.disabled = true;
        }
    });

    if (today === 4) {
        const itemStandardEmpanada = document.getElementById('item-empanada-standard');
        if (itemStandardEmpanada) {
            const btn = itemStandardEmpanada.querySelector('button');
            if (btn) { btn.disabled = true; btn.innerText = 'No disp.'; }
            itemStandardEmpanada.classList.add('promo-disabled');
            const info = itemStandardEmpanada.querySelector('.item-info');
            if (info) {
                const notice = document.createElement('span');
                notice.style.fontSize = '0.75rem'; notice.style.color = 'var(--accent)'; notice.style.fontWeight = 'bold';
                notice.innerText = '🔥 Solo disponible en Promo Jueves: ' + formatMoney(4000);
                info.appendChild(notice);
            }
        }
    }

    refreshStoreStatusUI();
    setInterval(refreshStoreStatusUI, 60000);
    renderPaymentMethods();
    handleOrderTypeChange();
});

function handleOrderTypeChange() {
    const orderType = document.getElementById('order-type')?.value;
    const deliveryAddressGroup = document.getElementById('delivery-address-group');
    const deliveryZoneGroup = document.getElementById('delivery-zone-group');
    if (deliveryAddressGroup) deliveryAddressGroup.style.display = orderType === 'Delivery' ? 'block' : 'none';
    if (deliveryZoneGroup) deliveryZoneGroup.style.display = orderType === 'Delivery' && getDeliveryZones().length ? 'block' : 'none';
    renderCart();
}

function renderPaymentMethods() {
    const methods = BenchoMoney.paymentMethods(CONFIG);
    const select = document.getElementById('payment-method');
    if (select) {
        const previous = select.value;
        select.replaceChildren(new Option('Selecciona un método de pago', ''));
        for (const method of methods) select.add(new Option(method.name, method.id));
        if (methods.some(method => method.id === previous)) select.value = previous;
    }
    const badges = document.getElementById('payment-method-badges');
    if (badges) badges.replaceChildren(...methods.map(method => {
        const span = document.createElement('span');
        span.textContent = method.name;
        return span;
    }));
}

function getCurrentLocationGPS() {
    if (!navigator.geolocation) { alert('Tu navegador no soporta geolocalización por GPS.'); return; }
    const btn = document.getElementById('btn-get-location');
    btn.innerText = '⌛ Obteniendo ubicación GPS...';

    navigator.geolocation.getCurrentPosition(
        (position) => {
            const lat = position.coords.latitude;
            const lng = position.coords.longitude;
            document.getElementById('order-address').value = `https://maps.google.com/?q=${lat},${lng}`;
            btn.innerText = '✅ ¡Ubicación obtenida!';
            setTimeout(() => { btn.innerText = '📍 Usar mi ubicación GPS actual (Google Maps)'; }, 3000);
        },
        (error) => {
            alert('No se pudo obtener la ubicación. Asegúrate de otorgar los permisos de GPS en tu dispositivo.');
            btn.innerText = '📍 Usar mi ubicación GPS actual (Google Maps)';
        },
        { enableHighAccuracy: true, timeout: 10000 }
    );
}

function getBurgersAndPromosInCartList() {
    const validNames = [];
    CONFIG.menuData.forEach(category => {
        category.items.forEach(item => { if (item.allowAddons) validNames.push(item.name); });
    });

    const result = [];
    Object.keys(cart).forEach(cartItemName => {
        if (validNames.some(vName => cartItemName.startsWith(vName))) {
            for (let i = 1; i <= cart[cartItemName].qty; i++) {
                const label = cart[cartItemName].qty > 1 ? `${cartItemName} (#${i})` : cartItemName;
                result.push({ fullName: cartItemName, uniqueLabel: label });
            }
        }
    });
    return result;
}

function handleAddToCart(uniqueId, catIndex, itemIndex, isFeatured) {
    if (!isStoreOpen()) { alert('Lo sentimos, en este momento el local está cerrado.'); return; }

    const menuItem = CONFIG.menuData[catIndex]?.items?.[itemIndex];
    if (!menuItem || !(menuItem.price > 0)) return;

    // Protección adicional: aunque alguien intente ejecutar la función manualmente,
    // un producto marcado como agotado nunca puede entrar al carrito.
    if (menuItem.outOfStock === true || menuItem.isSoldOut === true) {
        alert('Este producto está agotado temporalmente.');
        return;
    }

    if (menuItem.isAddon) {
        const availableBurgersAndPromos = getBurgersAndPromosInCartList();
        if (availableBurgersAndPromos.length === 0) {
            alert('Debes agregar al menos una hamburguesa o promo al carrito para seleccionar este adicional.');
            return;
        }
        currentAddonPending = { name: menuItem.name, price: menuItem.price, productId: menuItem.id };
        document.getElementById('addon-target-burger').innerHTML = availableBurgersAndPromos.map(b => `<option value="${escapeHtml(b.uniqueLabel)}">${escapeHtml(b.uniqueLabel)}</option>`).join('');
        document.getElementById('addon-modal-title').innerText = `🥓 ${menuItem.name}`;
        document.getElementById('addon-target-modal').style.display = 'flex';
        return;
    }

    let finalName = menuItem.name;
    const selectEl = document.getElementById(`sel-${uniqueId}`);
    if (selectEl) finalName += ` (${selectEl.value})`;

    addToCart(finalName, menuItem.price, menuItem.id);

}

function closeAddonModal() { document.getElementById('addon-target-modal').style.display = 'none'; currentAddonPending = null; }

function confirmAddonTarget() {
    if (!currentAddonPending) return;
    const selectedBurger = document.getElementById('addon-target-burger').value;
    const target = getBurgersAndPromosInCartList().find(item => item.uniqueLabel === selectedBurger);
    const parentProductId = target ? cart[target.fullName]?.productId : null;
    if (!parentProductId) { alert('No se pudo validar el producto asociado.'); return; }
    addToCart(`Adicional: ${currentAddonPending.name} [Para: ${selectedBurger}]`, currentAddonPending.price, currentAddonPending.productId, parentProductId);
    closeAddonModal();
}

function findProductIdByName(name) {
    const target = CONFIG.menuData.flatMap(category => category.items || []).find(item => item.name === name);
    return target?.id || null;
}

function repairCartProductIds() {
    Object.keys(cart).forEach(name => {
        const entry = cart[name];
        if (entry?.productId) return;
        if (name.startsWith('Adicional: ')) {
            const addonName = name.slice('Adicional: '.length).split(' [Para:')[0].trim();
            const addonId = findProductIdByName(addonName);
            if (addonId) {
                const targetText = name.includes('[Para:') ? name.split('[Para:')[1].replace(']', '').trim().replace(/ \(#[0-9]+\)$/, '') : '';
                const parentId = findProductIdByName(targetText);
                entry.productId = addonId;
                if (parentId) entry.parentProductId = parentId;
            }
        } else {
            entry.productId = findProductIdByName(name.replace(/ \([^)]*\)$/, ''));
        }
    });
}

function addToCart(name, price, productId = null, parentProductId = null) {
    if (!(Number(price) > 0)) return;
    productId = productId || findProductIdByName(name);
    if (!productId) {
        console.warn('Producto sin ID válido:', name);
        return;
    }
    if (cart[name]) {
        cart[name].qty = Math.min(50, cart[name].qty + 1);
    } else {
        cart[name] = { price: Number(price) || 0, qty: 1, productId, ...(parentProductId ? { parentProductId } : {}) };
    }
    renderCart();
}

function updateQuantity(name, change) {
    if (!cart[name]) return;

    let isAddonParent = false;
    CONFIG.menuData.forEach(category => {
        category.items.forEach(item => { if (item.allowAddons && name.startsWith(item.name)) isAddonParent = true; });
    });

    if (isAddonParent && change < 0) {
        const currentQty = cart[name].qty;
        const targetLabel = currentQty > 1 ? `${name} (#${currentQty})` : name;

        Object.keys(cart).forEach(itemKey => { if (itemKey.includes(`[Para: ${targetLabel}]`)) delete cart[itemKey]; });
        if (currentQty + change <= 0) {
            Object.keys(cart).forEach(itemKey => { if (itemKey.includes(`[Para: ${name}`)) delete cart[itemKey]; });
        }
    }

    cart[name].qty += change;
    if (cart[name].qty <= 0) delete cart[name];
    renderCart();
}

function resetCart() {
    if (Object.keys(cart).length === 0) return;
    cart = Object.create(null);
    try { localStorage.removeItem('bencho19_cart'); } catch {}
    renderCart();
}

document.getElementById('cart-items-container')?.addEventListener('click', event => {
    const button = event.target.closest('[data-qty-key]');
    if (!button) return;
    updateQuantity(button.dataset.qtyKey, Number(button.dataset.qtyChange));
});

function togglePaymentNotice() {}

function renderCart() {
    try { localStorage.setItem('bencho19_cart', JSON.stringify(cart)); } catch {}

    const container = document.getElementById('cart-items-container');
    const totalEl = document.getElementById('cart-total-val');
    const floatingBar = document.getElementById('floating-bar');
    
    repairCartProductIds();
    const keys = Object.keys(cart);
    if (keys.length === 0) {
        container.innerHTML = `<p style="color: var(--text-muted); text-align: center;">Tu carrito está vacío.</p>`;
        totalEl.innerHTML = moneyMarkup(0);
        floatingBar.style.display = 'none';
        return;
    }

    let html = '', subtotal = 0, totalItems = 0;

    keys.forEach(name => {
        const item = cart[name];
        const itemTotal = item.price * item.qty;
        subtotal += itemTotal;
        totalItems += item.qty;
        html += `
            <div class="cart-item">
                <div>
                    <div class="item-name">${escapeHtml(name)}</div>
                    <div style="font-size: 0.85rem; color: var(--text-muted);">${item.qty} × ${formatCop(item.price)} = ${moneyMarkup(itemTotal)}</div>
                </div>
                <div class="cart-item-controls">
                    <button class="btn-qty" type="button" data-qty-key="${escapeHtml(name)}" data-qty-change="-1" aria-label="Quitar una unidad">−</button>
                    <span>${item.qty}</span>
                    <button class="btn-qty" type="button" data-qty-key="${escapeHtml(name)}" data-qty-change="1" aria-label="Añadir una unidad">+</button>
                </div>
            </div>
        `;
    });

    const orderType = document.getElementById('order-type') ? document.getElementById('order-type').value : 'Delivery';
    const isWednesday = false;
    let deliveryCost = orderType === 'Delivery' && !isWednesday ? getDeliveryCost() : 0;

    if (orderType === 'Delivery') {
        html += `
            <div class="cart-item" style="border-top: 1px dashed ${isWednesday ? 'var(--primary)' : '#333'}; margin-top: 8px; padding-top: 10px;">
                <div>
                    <div class="item-name" style="color: ${isWednesday ? 'var(--primary)' : '#fff'};">🛵 Servicio de Delivery</div>
                    <div style="font-size: 0.85rem; color: ${isWednesday ? 'var(--primary)' : 'var(--text-muted)'}; font-weight: bold;">${isWednesday ? '¡GRATIS! (Promo Miércoles)' : formatMoney(getDeliveryCost())}</div>
                </div>
            </div>
        `;
    } else {
        html += `
            <div class="cart-item" style="border-top: 1px dashed #333; margin-top: 8px; padding-top: 10px;">
                <div>
                    <div class="item-name" style="color: var(--accent);">🍽️ Servicio: ${escapeHtml(orderType)}</div>
                    <div style="font-size: 0.85rem; color: var(--primary); font-weight: bold;">Sin costo adicional</div>
                </div>
            </div>
        `;
    }

    container.innerHTML = html;
    const total = subtotal + deliveryCost;
    totalEl.innerHTML = moneyMarkup(total);

    document.getElementById('floating-count').innerText = `${totalItems} ${totalItems === 1 ? 'producto' : 'productos'}`;
    document.getElementById('floating-total').innerText = `Total: ${formatCop(total)}`;
    floatingBar.style.display = 'flex';
}

function formatCop(value) {
    return (Number(value) || 0).toLocaleString('es-CO', { maximumFractionDigits: 2 }) + ' COP';
}
function orderEquivalences(cop) {
    return BenchoMoney.equivalents(cop, CONFIG).map(({ currency, value }) =>
        '≈ ' + value.toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' ' + currency
    );
}
function formatMoney(cop) {
    const equivalents = orderEquivalences(cop);
    return formatCop(cop) + (equivalents.length ? ' · ' + equivalents.join(' · ') : '');
}
function moneyMarkup(cop) {
    const equivalents = orderEquivalences(cop);
    return '<span class="money-block"><strong>' + escapeHtml(formatCop(cop)) + '</strong>' +
        (equivalents.length ? '<span class="money-equivalents">' + equivalents.map(escapeHtml).join(' <i>·</i> ') + '</span>' : '') + '</span>';
}
function sendOrderToWhatsApp() {
    const names = Object.keys(cart);
    if (!names.length) return alert('Agrega al menos un producto al carrito.');
    if (!isStoreOpen()) return alert('El local está cerrado. Puedes preparar el pedido para enviarlo cuando abra.');
    const name = document.getElementById('client-name')?.value.trim();
    const methodId = document.getElementById('payment-method')?.value || '';
    const method = BenchoMoney.paymentMethods(CONFIG).find(item => item.id === methodId);
    if (!method) return alert('Selecciona un método de pago disponible.');
    const type = document.getElementById('order-type')?.value || 'Delivery';
    const address = document.getElementById('order-address')?.value.trim() || '';
    if (!name || (type === 'Delivery' && !address)) return alert('Completa tu nombre y la dirección de entrega.');
    const raw = String(CONFIG.restaurant?.whatsapp || '').replace(/\D/g,'');
    const phone = /^0\d{10}$/.test(raw) ? '58'+raw.slice(1) : raw;
    if (!/^\d{10,15}$/.test(phone)) return alert('El WhatsApp del restaurante no está configurado.');
    const currency = formatCop;
    let subtotal = 0;
    const details = names.map((label, i) => {
      const line = cart[label];
      const price = Number(line.price)||0;
      const quantity = Math.max(1,Number(line.qty)||1);
      subtotal += price*quantity;
      return `${i+1}. ${label}\n   ${quantity} x ${currency(price)} = ${currency(price*quantity)}`;
    });
    const shipping = type === 'Delivery' && true ? Number(getDeliveryCost()) || 0 : 0;
    const zone = type==='Delivery' ? getSelectedDeliveryZone()?.name : '';
    const notes = document.getElementById('food-notes')?.value.trim()||'';
    const message = [`*Pedido para Bencho 1:9*`, `Cliente: ${name}`, '', ...details, '',
      `Subtotal: ${currency(subtotal)}`, type==='Delivery' ? `Delivery estimado: ${currency(shipping)}${false ? ' (promoción miércoles)' : ''}` : '',
      `Total estimado: ${currency(subtotal+shipping)}`,
      ...(orderEquivalences(subtotal+shipping).length ? [`Equivalencias estimadas: ${orderEquivalences(subtotal+shipping).join(' | ')}`] : []),
      `Entrega: ${type}`,
      `Método de pago: ${method.name}`,
      zone ? `Zona: ${zone}` : '', type==='Delivery' ? `Dirección: ${address}` : '', notes ? `Observaciones: ${notes}` : '',
      '', '*Precio final y disponibilidad sujetos a confirmación del restaurante.*',
      'Este pedido se envía cuando confirmes el mensaje en WhatsApp.'].filter(v=>v!=='').join('\n');
    window.location.assign(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`);
}

function safeLink(value) { try { const url=new URL(value,location.href);return ['https:','http:'].includes(url.protocol) && !url.username && !url.password ? url.href : '#'; } catch { return '#'; } }

